head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.clickId;
scwin.gIsurCd;
scwin.key_dsicls_schdl_adm_dd = '';
scwin.key_bydd_seq = '';
scwin.key_integ_usr_id = '';
scwin.vScrenID = 'ULDSTF30008.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    var url = "/DisclosureSchedule.do?method=listDelistRealInvstg";
    url += "&FROM_DATE=" + edt_SDate.getValue();
    url += "&TO_DATE=" + edt_EDate.getValue();
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_setId = function(row) {
    scwin.key_dsicls_schdl_adm_dd = dts_Grid.getCellData(row, "DISCLS_SCHDL_ADM_DD");
    scwin.key_bydd_seq = dts_Grid.getCellData(row, "BYDD_SEQ");
    scwin.key_integ_usr_id = dts_Grid.getCellData(row, "INTEG_USR_ID");
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_Input_onclick = async function() {
    scwin.key_dsicls_schdl_adm_dd = '';
    scwin.key_bydd_seq = '';
    scwin.key_integ_usr_id = '';
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF30009.gfm", "상장적격성 실질심사 등록", 200, 100, 480, 390, "window");
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnFail = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (rowcount <= 0) {
        dts_Grid.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
    if (colid == 'COM_ABBRV') {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        scwin.gIsurCd = scwin.gIsurCd.substring(0, 5);
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == 'DISCLS_SCHDL_ADM_CONTN') {
        if (dts_Grid.getCellData(row, "DISCLS_SCHDL_ACT_STAT_CD") != '0') {
            $c.win.alert("공시일정상태가 미확정이 아닌경우 수정할 수 없습니다.");
        } else {
            scwin.fn_setId(row);
            await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF30009.gfm", "상장적격성실질심사 수정", 200, 100, 480, 390, "window");
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (window.event.keyCode == 40) {
        //아래화살표눌렀을때 그리드로 포커스
        Grd_com_isur.focus();
    } else {
        if (window.event.keyCode == 13) {
            $c.cm.fn_com_Confirm_set();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜	
    edt_EDate.setValue(vCurDate);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    $c.stf.showObj(panel_mkt, false);

    //fn_Search();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
